from typing import List

def find_correctly_typed_positions(s: str, t: str) -> List[int]:
    positions = []
    j = 0
    for c in s:
        while j < len(t) and t[j] != c:
            j += 1
        if j < len(t) and t[j] == c:
            positions.append(j + 1)
            j += 1
    return positions
